import os, csv, json, datetime
def process(path):
    out=[]
    for f in os.listdir(path):
        try:
            for i,row in enumerate(csv.DictReader(open(path+'/'+f))):
                if row['documento']=='documento': continue
                try: row['contatos']=json.loads(row['contatos'])
                except: row['contatos']=[]
                row['loaded_at']=datetime.datetime.now().isoformat()
                out.append(row)
        except: pass
    return out
